request_examples.code:
const BASE_URL = "{{BASE_URL}}";
const API_KEY = "{{API_KEY}}";
const jobId = "job_3f9c2a7e5b8d4c1fa0e6b2d9c7f41a58";

const resp = await fetch(`${BASE_URL}/v1/jobs/${jobId}/cancel`, {
  method: "POST",
  headers: { Authorization: `Bearer ${API_KEY}` },
});
if (resp.status === 202) {
  const job = await resp.json(); // 最后已知状态，可能仍是 queued / running
  console.log("cancel requested", job.status);
} else {
  console.error(resp.status, await resp.json());
}

